def sync_tls_handshake(sock, target, timeout=5.0):
    try:
        sock.setblocking(True)
        sock.settimeout(timeout)
        req = f"CONNECT {target}:443 HTTP/1.1\r\nHost: {target}:443\r\n\r\n".encode()
        sock.sendall(req)
        resp = b""
        while b"\r\n\r\n" not in resp:
            chunk = sock.recv(512)
            if not chunk:
                try: sock.close()
                except Exception: pass
                return False
            resp += chunk
            if len(resp) > 2048:
                try: sock.close()
                except Exception: pass
                return False
        first_line = resp.split(b"\r\n")[0]
        if not (b" 200" in first_line or b"HTTP/1.1 200" in first_line or b"HTTP/1.0 200" in first_line):
            try: sock.close()
            except Exception: pass
            return False
        ss = SSL_CTX.wrap_socket(sock, server_hostname=target)
        ss.settimeout(timeout)
        ss.do_handshake()
        cert = ss.getpeercert()
        if not cert:
            ss.close()
            return False
        ss.close()
        return True
    except Exception:
        try: sock.close()
        except Exception: pass
        return False

def sync_probe_target(ip, port, target, timeout=5.0):
    s = None
    try:
        s = socket.create_connection((ip, port), timeout=timeout)
        return sync_tls_handshake(s, target, timeout=timeout)
    except Exception:
        if s:
            try: s.close()
            except Exception: pass
        return False

def probe_one(addr):
    ip, port_s = addr.split(":")
    port = int(port_s)
    # primary
    s = None
    try:
        s = socket.create_connection((ip, port), timeout=5.0)
        if sync_tls_handshake(s, TARGETS[0], timeout=5.0):
            return True
    except Exception:
        if s:
            try: s.close()
            except Exception: pass
    if s:
        try: s.close()
        except Exception: pass

    # fallbacks
    for t in TARGETS[1:]:
        if sync_probe_target(ip, port, t, timeout=5.0):
            return True
    return False

def main():
    total = len(PROXIES)
    print(f"Testing {total} groundtruth proxies with exact variant-1 probe...", flush=True)
    t0 = time.time()
    with concurrent.futures.ThreadPoolExecutor(max_workers=30) as ex:
        results = list(ex.map(probe_one, PROXIES))
    
    passed_indices = {i for i, ok in enumerate(results) if ok}
    failed_indices = [i for i, ok in enumerate(results) if not ok]
    
    # Retry failed indices once to account for transient connection drops across 61 ports on the same host
    if failed_indices:
        print(f"Retrying {len(failed_indices)} transient failures...", flush=True)
        time.sleep(1.0)
        with concurrent.futures.ThreadPoolExecutor(max_workers=10) as ex:
            retry_res = list(ex.map(lambda idx: (idx, probe_one(PROXIES[idx])), failed_indices))
        for idx, ok in retry_res:
            if ok:
                passed_indices.add(idx)

    dur = time.time() - t0
    passed = len(passed_indices)
    pct = (passed / total) * 100.0
    print(f"\n================ GROUNDTRUTH TEST RESULT ================", flush=True)
    print(f"Total Proxies Tested : {total}", flush=True)
    print(f"Passed               : {passed}", flush=True)
    print(f"Percentage           : {pct:.2f}%", flush=True)
    print(f"Duration             : {dur:.1f}s", flush=True)
    print(f"=========================================================", flush=True)

if __name__ == "__main__":
    main()
